package com.rustyledger;

import java.math.BigDecimal;

class Account {
    final String id;
    final String tier;
    final String currency;
    BigDecimal balance;

    Account(String id, String tier, String currency, BigDecimal balance) {
        this.id = id;
        this.tier = tier;
        this.currency = currency;
        this.balance = balance.setScale(2);
    }

    boolean isStandard() { return "STANDARD".equals(tier); }
    boolean isPremium() { return "PREMIUM".equals(tier); }
    boolean isStaff() { return "STAFF".equals(tier); }

    BigDecimal getOverdraftLimit() {
        return isPremium() ? new BigDecimal("500.00") : BigDecimal.ZERO;
    }

    BigDecimal getDailyLimit() {
        if (isStandard()) return new BigDecimal("5000.00");
        if (isPremium()) return new BigDecimal("20000.00");
        return new BigDecimal("50000.00");
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

class AccountStore {
    private final Map<String, Account> accounts = new HashMap<>();
    private final Map<String, BigDecimal> dailyUsage = new HashMap<>();

    void add(Account account) {
        if (accounts.containsKey(account.id)) {
            throw new IllegalStateException("ACCOUNT EXISTS: " + account.id);
        }
        accounts.put(account.id, account);
    }

    Account get(String id) {
        return accounts.get(id);
    }

    BigDecimal getUsedToday(String id, String date) {
        return dailyUsage.getOrDefault(id + "|" + date, BigDecimal.ZERO.setScale(2));
    }

    void markUsage(String id, String date, BigDecimal amount) {
        String key = id + "|" + date;
        dailyUsage.put(key, getUsedToday(id, date).add(amount));
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.math.RoundingMode;

class CurrencyLogic {
    static BigDecimal rate(String currency) {
        return switch (currency) {
            case "EUR" -> new BigDecimal("4.30");
            case "USD" -> new BigDecimal("4.00");
            default -> new BigDecimal("1.00");
        };
    }

    static BigDecimal convert(BigDecimal amount, String from, String to, Account account) {
        if (from.equals(to)) return amount;
        BigDecimal inPln = amount.multiply(rate(from)).setScale(4, RoundingMode.HALF_UP);
        BigDecimal result = inPln.divide(rate(to), 4, RoundingMode.HALF_UP);
        if (!account.isStaff()) {
            result = result.multiply(new BigDecimal("0.985"));
        }
        return result.setScale(2, RoundingMode.HALF_DOWN);
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.math.RoundingMode;

class FeeLogic {
    static BigDecimal calculateTransferFee(Account account, BigDecimal amount) {
        if (account.isStaff()) return new BigDecimal("0.00").setScale(2);
        if (account.isStandard()) {
            BigDecimal fee = amount.multiply(new BigDecimal("0.005"))
                    .setScale(2, RoundingMode.HALF_UP);
            return fee.max(new BigDecimal("0.20"));
        }
        BigDecimal fee = amount.multiply(new BigDecimal("0.0025"))
                .setScale(2, RoundingMode.HALF_UP);
        return fee.max(new BigDecimal("0.10")).min(new BigDecimal("5.00"));
    }

    static BigDecimal calculateWithdrawalFee(Account account) {
        return account.isStandard() ? new BigDecimal("1.00") : new BigDecimal("0.00");
    }
}

package com.rustyledger;

import java.math.BigDecimal;

class TransactionRecord {
    final String type;
    final String date;
    final String fromId;
    final String toId;
    final BigDecimal amount;
    final String currency;
    final BigDecimal fee;
    final BigDecimal credited;
    String reversed = "N";

    TransactionRecord(String type, String date, String from, String to, 
                     BigDecimal amt, String cur, BigDecimal fee, BigDecimal cred) {
        this.type = type;
        this.date = date;
        this.fromId = from;
        this.toId = to;
        this.amount = amt;
        this.currency = cur;
        this.fee = fee;
        this.credited = cred;
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.*;

class Reporting {
    private final List<String> audit = new ArrayList<>();
    private final Map<String, int[]> counts = new HashMap<>();
    private final Map<String, Map<String, BigDecimal>> fees = new HashMap<>();
    private int auditSeq = 0;

    void record(String verb, String date, String outcome) {
        auditSeq++;
        audit.add(String.format("%03d  %s %s %s", auditSeq, verb, date, outcome));
    }

    void count(String date, int slot) {
        counts.computeIfAbsent(date, d -> new int[2])[slot]++;
    }

    void addFee(String date, String currency, BigDecimal delta) {
        if (delta.signum() == 0) return;
        Map<String, BigDecimal> dayFees = fees.computeIfAbsent(date, d -> new TreeMap<>());
        dayFees.put(currency, dayFees.getOrDefault(currency, BigDecimal.ZERO).add(delta));
    }

    List<String> getAuditLog() { return new ArrayList<>(audit); }

    String getDailyReport(String date) {
        int[] c = counts.get(date);
        int ok = (c == null) ? 0 : c[0];
        int rejected = (c == null) ? 0 : c[1];
        Map<String, BigDecimal> f = fees.get(date);
        String feeText = "none";
        if (f != null && !f.isEmpty()) {
            List<String> parts = new ArrayList<>();
            f.forEach((cur, val) -> parts.add(val.setScale(2) + " " + cur));
            feeText = String.join(", ", parts);
        }
        return "REPORT " + date + "\nok: " + ok + "\nrejected: " + rejected + "\nfees: " + feeText;
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.*;

class RealLedger implements Ledger {
    private final AccountStore accounts = new AccountStore();
    private final Reporting reporting = new Reporting();
    private final Map<String, TransactionRecord> txs = new LinkedHashMap<>();
    private int txSeq = 0;

    public void openAccount(String id, String tier, String cur, String bal) {
        if (id == null || id.isBlank() || id.contains("|")) 
            throw new IllegalArgumentException("INVALID ACCOUNT ID");
        if (!Set.of("STANDARD", "PREMIUM", "STAFF").contains(tier))
            throw new IllegalArgumentException("INVALID TIER: " + tier);
        if (!Set.of("PLN", "EUR", "USD").contains(cur))
            throw new IllegalArgumentException("INVALID CURRENCY: " + cur);
        if (bal == null || !bal.matches("\\d+(\\.\\d{1,2})?"))
            throw new IllegalArgumentException("INVALID AMOUNT: " + bal);
        accounts.add(new Account(id, tier, cur, new BigDecimal(bal)));
    }

    public String balance(String id) {
        Account a = accounts.get(id);
        if (a == null) throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + id);
        return a.balance.setScale(2) + " " + a.currency;
    }

    public List<String> auditLog() { return reporting.getAuditLog(); }
    public String dailyReport(String date) { return reporting.getDailyReport(date); }

    public String submit(String line) {
        if (line == null || line.isBlank()) return reject("???", null, "BAD_INSTRUCTION", "empty instruction");
        String[] f = line.split("\\|", -1);
        String verb = f[0];
        Map<String, Integer> expected = Map.of("TRANSFER", 6, "WITHDRAW", 4, "DEPOSIT", 4, "REVERSE", 3);
        if (!expected.containsKey(verb)) return reject("???", null, "BAD_INSTRUCTION", "unknown verb " + verb);
        if (f.length != expected.get(verb)) return reject(verb, null, "BAD_INSTRUCTION", verb + " needs " + expected.get(verb) + " fields");
        String date = f[1];
        if (!date.matches("\\d{4}-\\d{2}-\\d{2}")) return reject(verb, null, "BAD_DATE", date);
        return dispatch(verb, date, f);
    }

    private String dispatch(String verb, String date, String[] f) {
        if (verb.equals("REVERSE")) return doReverse(date, f[2]);
        String amtText = verb.equals("TRANSFER") ? f[4] : f[3];
        if (!amtText.matches("\\d+(\\.\\d{1,2})?")) return reject(verb, date, "BAD_AMOUNT", amtText);
        BigDecimal amount = new BigDecimal(amtText).setScale(2);
        if (amount.signum() <= 0) return reject(verb, date, "BAD_AMOUNT", amtText);
        return switch (verb) {
            case "TRANSFER" -> doTransfer(date, f[2], f[3], amount, f[5]);
            case "WITHDRAW" -> doWithdraw(date, f[2], amount);
            default -> doDeposit(date, f[2], amount);
        };
    }

    private String doTransfer(String date, String fromId, String toId, BigDecimal amount, String cur) {
        Account from = accounts.get(fromId);
        if (from == null) return reject("TRANSFER", date, "UNKNOWN_ACCOUNT", fromId);
        Account to = accounts.get(toId);
        if (to == null) return reject("TRANSFER", date, "UNKNOWN_ACCOUNT", toId);
        if (fromId.equals(toId)) return reject("TRANSFER", date, "SAME_ACCOUNT", "cannot transfer to the same account");
        if (!from.currency.equals(cur)) return reject("TRANSFER", date, "CURRENCY_MISMATCH", fromId + " holds " + from.currency);
        BigDecimal fee = FeeLogic.calculateTransferFee(from, amount);
        String err = checkFunds(date, from, amount, fee);
        if (err != null) return reject("TRANSFER", date, err.split(": ")[0], err.split(": ")[1]);
        BigDecimal credited = CurrencyLogic.convert(amount, from.currency, to.currency, from);
        from.balance = from.balance.subtract(amount.add(fee));
        to.balance = to.balance.add(credited);
        accounts.markUsage(fromId, date, amount);
        String txId = nextTx();
        txs.put(txId, new TransactionRecord("TRANSFER", date, fromId, toId, amount, cur, fee, credited));
        reporting.addFee(date, from.currency, fee);
        return accept("TRANSFER", date, txId, "fee=" + fee + " " + from.currency);
    }

    private String doWithdraw(String date, String id, BigDecimal amount) {
        Account a = accounts.get(id);
        if (a == null) return reject("WITHDRAW", date, "UNKNOWN_ACCOUNT", id);
        BigDecimal fee = FeeLogic.calculateWithdrawalFee(a);
        String err = checkFunds(date, a, amount, fee);
        if (err != null) return reject("WITHDRAW", date, err.split(": ")[0], err.split(": ")[1]);
        a.balance = a.balance.subtract(amount.add(fee));
        accounts.markUsage(id, date, amount);
        String txId = nextTx();
        txs.put(txId, new TransactionRecord("WITHDRAW", date, id, "", amount, a.currency, fee, amount));
        reporting.addFee(date, a.currency, fee);
        return accept("WITHDRAW", date, txId, "fee=" + fee + " " + a.currency);
    }

    private String doDeposit(String date, String id, BigDecimal amount) {
        Account a = accounts.get(id);
        if (a == null) return reject("DEPOSIT", date, "UNKNOWN_ACCOUNT", id);
        a.balance = a.balance.add(amount);
        String txId = nextTx();
        txs.put(txId, new TransactionRecord("DEPOSIT", date, id, "", amount, a.currency, BigDecimal.ZERO, amount));
        return accept("DEPOSIT", date, txId, "fee=0.00 " + a.currency);
    }

    private String doReverse(String date, String id) {
        TransactionRecord tx = txs.get(id);
        if (tx == null) return reject("REVERSE", date, "UNKNOWN_TX", id);
        if (!tx.type.equals("TRANSFER")) return reject("REVERSE", date, "NOT_REVERSIBLE", id + " is a " + tx.type);
        if (tx.reversed.equals("Y")) return reject("REVERSE", date, "ALREADY_REVERSED", id);
        if (!tx.date.equals(date)) return reject("REVERSE", date, "REVERSAL_WINDOW", id + " was made on " + tx.date);
        Account from = accounts.get(tx.fromId);
        Account to = accounts.get(tx.toId);
        to.balance = to.balance.subtract(tx.credited);
        BigDecimal back = tx.amount;
        if (from.isPremium()) {
            back = back.add(tx.fee);
            reporting.addFee(date, from.currency, tx.fee.negate());
        }
        from.balance = from.balance.add(back);
        tx.reversed = "Y";
        String nTx = nextTx();
        txs.put(nTx, new TransactionRecord("REVERSE", date, tx.fromId, tx.toId, tx.amount, tx.currency, BigDecimal.ZERO, tx.credited));
        txs.get(nTx).reversed = "Y";
        return accept("REVERSE", date, nTx, "reversed " + id);
    }

    private String checkFunds(String date, Account a, BigDecimal amount, BigDecimal fee) {
        BigDecimal limit = a.getDailyLimit();
        if (accounts.getUsedToday(a.id, date).add(amount).compareTo(limit) > 0)
            return "LIMIT_EXCEEDED: daily limit " + limit + " for " + a.tier;
        BigDecimal needed = amount.add(fee);
        if (a.balance.subtract(needed).compareTo(a.getOverdraftLimit().negate()) < 0)
            return "INSUFFICIENT_FUNDS: balance " + a.balance + " " + a.currency + ", needed " + needed + " " + a.currency;
        return null;
    }

    private String nextTx() { return String.format("TX-%06d", ++txSeq); }
    private String accept(String v, String d, String id, String e) {
        reporting.count(d, 0);
        reporting.record(v, d, "OK " + id);
        return "OK " + id + " " + e;
    }
    private String reject(String v, String d, String c, String m) {
        if (d != null) reporting.count(d, 1);
        reporting.record(v, d == null ? "????-??-??" : d, "REJECTED " + c);
        return "REJECTED " + c + ": " + m;
    }
}

